import { onUnmounted, ref } from 'vue'

/**
 * Menjalankan `pemeriksa` berkala selama pemohon menunggu sesuatu diproses di
 * server — dipakai halaman reset kata sandi supaya form kata sandi muncul
 * sendiri begitu admin menyetujui, tanpa pemohon menekan tombol.
 *
 * Perilaku yang dijaga di sini:
 *   - melewati pemeriksaan saat halaman/app di background, dan langsung
 *     memeriksa lagi begitu kembali ke depan (timer HP di-throttle, jadi
 *     menunggu tick berikutnya terasa lambat)
 *   - MELAMBAT, bukan berhenti, setelah `cepatSelamaMs`. Persetujuan admin bisa
 *     datang berjam-jam kemudian dan tidak ada tombol cek manual, jadi berhenti
 *     total akan membuat halaman buntu. Melambat menjaga halaman tetap hidup
 *     tanpa menabrak rate limit `check_reset_status` (300/jam per IP+email):
 *     15 detik selama 30 menit = 120 panggilan, lalu 60 detik = 60/jam.
 *   - berhenti saat komponen dilepas
 *
 * @param {() => Promise<void>} pemeriksa dipanggil tiap interval; error yang
 *   dilemparnya diteruskan ke `onError`
 * @param {{intervalMs?: number, intervalLambatMs?: number, cepatSelamaMs?: number,
 *   onError?: (e: unknown) => void}} opsi
 */
export function useAutoCheck(pemeriksa, opsi = {}) {
	const {
		intervalMs = 15000,
		intervalLambatMs = 60000,
		cepatSelamaMs = 30 * 60 * 1000,
		onError,
	} = opsi

	const aktif = ref(false)
	let timer = null
	let mulaiPada = 0
	let sedangJalan = false

	function stop() {
		if (timer) {
			clearTimeout(timer)
			timer = null
		}
		document.removeEventListener('visibilitychange', saatTerlihat)
		aktif.value = false
	}

	function start() {
		stop()
		mulaiPada = Date.now()
		aktif.value = true
		document.addEventListener('visibilitychange', saatTerlihat)
		jadwalkan()
	}

	// setTimeout berantai, bukan setInterval, supaya jeda bisa berubah di tengah
	// jalan saat berpindah dari mode cepat ke lambat.
	function jadwalkan() {
		const lambat = Date.now() - mulaiPada > cepatSelamaMs
		timer = setTimeout(tick, lambat ? intervalLambatMs : intervalMs)
	}

	async function jalankan() {
		// Jangan menumpuk kalau panggilan sebelumnya belum selesai.
		if (sedangJalan) return
		sedangJalan = true
		try {
			await pemeriksa()
		} catch (error) {
			onError?.(error)
		} finally {
			sedangJalan = false
		}
	}

	async function tick() {
		// Saat app di background pemohon tidak melihat apa pun — lewati saja
		// supaya kuota tidak terbuang, tapi jadwalnya tetap berjalan.
		if (!document.hidden) await jalankan()
		// `stop()` bisa dipanggil dari dalam `pemeriksa`; jangan jadwalkan ulang
		// kalau polling sudah dimatikan.
		if (aktif.value) jadwalkan()
	}

	function saatTerlihat() {
		if (!document.hidden) jalankan()
	}

	onUnmounted(stop)

	return { aktif, start, stop, periksaSekarang: jalankan }
}
